<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';
require_role('information_officer');
$user = current_user();
$uid = (int)($user['id'] ?? $user['user_id'] ?? 0);
$db = Database::getConnection();
function bm_e($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function bm_redirect(string $q=''): never { header('Location: '.url('privacy/breach_management.php').$q); exit; }
if (session_status() !== PHP_SESSION_ACTIVE) { session_start(); }
if (empty($_SESSION['bm_csrf'])) { $_SESSION['bm_csrf'] = bin2hex(random_bytes(32)); }
$csrf = (string)$_SESSION['bm_csrf'];
function bm_log(mysqli $db,int $uid,string $action,int $id): void {
    $s=$db->prepare("INSERT INTO io_audit_events(actor_user_id,action,entity_type,entity_id) VALUES(?,?, 'security_incident', ?)");
    if($s){$sid=(string)$id;$s->bind_param('iss',$uid,$action,$sid);$s->execute();$s->close();}
}
$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!hash_equals($csrf,(string)($_POST['csrf']??''))){http_response_code(400);exit('Invalid security token. Refresh the page and try again.');}
    $action=(string)($_POST['action']??'');
    if($action==='create'){
        $ref=trim((string)($_POST['incident_reference']??'')); if($ref==='')$ref='PI-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(3)));
        $type=(string)($_POST['incident_type']??'other');
        $allowed=['unauthorised_access','loss_or_theft','wrong_recipient','unauthorised_disclosure','malware_or_ransomware','system_compromise','improper_disposal','availability','other'];
        if(!in_array($type,$allowed,true))$type='other';
        $severity=(string)($_POST['severity']??'medium');if(!in_array($severity,['low','medium','high','critical'],true))$severity='medium';
        $title=trim((string)($_POST['title']??''));$summary=trim((string)($_POST['summary']??''));
        $discovered=trim((string)($_POST['discovered_at']??''));$occurred=trim((string)($_POST['occurred_at']??''));
        $category=trim((string)($_POST['information_categories']??''));$subjects=trim((string)($_POST['data_subject_categories']??''));
        $systems=trim((string)($_POST['systems_affected']??''));$count=max(0,(int)($_POST['estimated_subjects']??0));
        $likelihood=max(1,min(5,(int)($_POST['risk_likelihood']??3)));$impact=max(1,min(5,(int)($_POST['risk_impact']??3)));
        $risk=$likelihood*$impact;
        if($title===''||$summary===''||$category===''||$subjects==='')$message='Complete the title, summary, information categories and affected data-subject categories.';
        else{
            $s=$db->prepare("INSERT INTO io_security_incidents(incident_reference,title,incident_type,severity,summary,occurred_at,discovered_at,information_categories,data_subject_categories,systems_affected,estimated_subjects,risk_likelihood,risk_impact,risk_score,status,reported_by) VALUES(?,?,?,?,?,NULLIF(?,''),NULLIF(?,''),?,?,?,?,?,?,?,'reported',?)");
            if($s){$s->bind_param('ssssssssssiiiii',$ref,$title,$type,$severity,$summary,$occurred,$discovered,$category,$subjects,$systems,$count,$likelihood,$impact,$risk,$uid);if($s->execute()){$id=(int)$s->insert_id;bm_log($db,$uid,'incident_created',$id);bm_redirect('?incident='.$id.'&created=1');}$message='Unable to create incident: '.$s->error;$s->close();}
        }
    } elseif($action==='update'){
        $id=(int)($_POST['incident_id']??0);$status=(string)($_POST['status']??'investigating');
        $statuses=['reported','triage','investigating','containment','notification_assessment','remediation','monitoring','resolved','closed'];
        if(!in_array($status,$statuses,true))$status='investigating';
        $severity=(string)($_POST['severity']??'medium');if(!in_array($severity,['low','medium','high','critical'],true))$severity='medium';
        $likelihood=max(1,min(5,(int)($_POST['risk_likelihood']??3)));$impact=max(1,min(5,(int)($_POST['risk_impact']??3)));$risk=$likelihood*$impact;
        $assessment=trim((string)($_POST['risk_assessment']??''));$investigation=trim((string)($_POST['investigation_findings']??''));
        $containment=trim((string)($_POST['containment_summary']??''));$notify=(string)($_POST['notification_required']??'undetermined');
        if(!in_array($notify,['undetermined','yes','no'],true))$notify='undetermined';
        $basis=trim((string)($_POST['notification_reason']??''));$contained=trim((string)($_POST['contained_at']??''));
        $s=$db->prepare("UPDATE io_security_incidents SET status=?,severity=?,risk_likelihood=?,risk_impact=?,risk_score=?,risk_assessment=?,investigation_findings=?,containment_summary=?,contained_at=NULLIF(?,''),notification_required=?,notification_reason=?,last_updated_by=? WHERE id=?");
        if($s){$s->bind_param('ssiiissssssii',$status,$severity,$likelihood,$impact,$risk,$assessment,$investigation,$containment,$contained,$notify,$basis,$uid,$id);if($s->execute()){bm_log($db,$uid,'incident_updated',$id);bm_redirect('?incident='.$id.'&updated=1');}$message='Unable to update incident: '.$s->error;$s->close();}
    } elseif($action==='add_action'){
        $id=(int)($_POST['incident_id']??0);$desc=trim((string)($_POST['action_description']??''));$owner=trim((string)($_POST['action_owner']??''));$due=trim((string)($_POST['due_date']??''));$priority=(string)($_POST['priority']??'medium');
        if(!in_array($priority,['low','medium','high','urgent'],true))$priority='medium';
        if($desc==='')$message='Describe the corrective or preventive action.';
        else{$s=$db->prepare("INSERT INTO io_security_incident_actions(incident_id,action_description,owner_name,priority,due_date,created_by) VALUES(?,?,?,?,NULLIF(?,''),?)");if($s){$s->bind_param('issssi',$id,$desc,$owner,$priority,$due,$uid);if($s->execute()){bm_log($db,$uid,'corrective_action_added',$id);bm_redirect('?incident='.$id.'&action_added=1');}$message='Unable to add action: '.$s->error;$s->close();}}
    } elseif($action==='update_action'){
        $aid=(int)($_POST['action_id']??0);$id=(int)($_POST['incident_id']??0);$status=(string)($_POST['action_status']??'open');
        if(!in_array($status,['open','in_progress','completed','overdue','cancelled'],true))$status='open';
        $s=$db->prepare("UPDATE io_security_incident_actions SET status=?,completed_at=IF(?='completed',NOW(),NULL),updated_by=? WHERE id=? AND incident_id=?");
        if($s){$s->bind_param('ssiii',$status,$status,$uid,$aid,$id);$s->execute();$s->close();bm_log($db,$uid,'corrective_action_updated',$id);bm_redirect('?incident='.$id);}
    } elseif($action==='notification'){
        $id=(int)($_POST['incident_id']??0);$recipient=(string)($_POST['recipient_type']??'regulator');if(!in_array($recipient,['regulator','affected_subjects','other'],true))$recipient='other';
        $status=(string)($_POST['notification_status']??'not_required');if(!in_array($status,['not_assessed','not_required','pending','approved','sent','failed'],true))$status='not_assessed';
        $sent=trim((string)($_POST['sent_at']??''));$ref=trim((string)($_POST['notification_reference']??''));$notes=trim((string)($_POST['notification_notes']??''));
        $s=$db->prepare("INSERT INTO io_security_breach_notifications(incident_id,recipient_type,notification_status,sent_at,notification_reference,notes,recorded_by) VALUES(?,?,?,NULLIF(?,''),?,?,?)");
        if($s){$s->bind_param('isssssi',$id,$recipient,$status,$sent,$ref,$notes,$uid);if($s->execute()){bm_log($db,$uid,'breach_notification_recorded',$id);bm_redirect('?incident='.$id.'&notification_added=1');}$message='Unable to record notification: '.$s->error;$s->close();}
    } elseif($action==='add_note'){
        $id=(int)($_POST['incident_id']??0);$note=trim((string)($_POST['note_text']??''));$kind=(string)($_POST['note_type']??'investigation');
        if(!in_array($kind,['investigation','evidence_reference','decision','communications'],true))$kind='investigation';
        if($note!==''){$s=$db->prepare("INSERT INTO io_security_incident_notes(incident_id,note_type,note_text,created_by) VALUES(?,?,?,?)");if($s){$s->bind_param('issi',$id,$kind,$note,$uid);$s->execute();$s->close();bm_log($db,$uid,'incident_note_added',$id);bm_redirect('?incident='.$id);}}
    }
}
$selected=(int)($_GET['incident']??0);
$incidents=[];$r=$db->query("SELECT id,incident_reference,title,incident_type,severity,status,risk_score,discovered_at,created_at FROM io_security_incidents ORDER BY FIELD(severity,'critical','high','medium','low'),created_at DESC LIMIT 250");if($r)while($row=$r->fetch_assoc())$incidents[]=$row;
$incident=null;if($selected){$s=$db->prepare("SELECT * FROM io_security_incidents WHERE id=?");$s->bind_param('i',$selected);$s->execute();$incident=$s->get_result()->fetch_assoc();$s->close();}
$counts=['open'=>0,'critical'=>0,'notification'=>0,'actions'=>0];$r=$db->query("SELECT COUNT(*) n FROM io_security_incidents WHERE status NOT IN('resolved','closed')");if($r)$counts['open']=(int)$r->fetch_assoc()['n'];$r=$db->query("SELECT COUNT(*) n FROM io_security_incidents WHERE severity='critical' AND status NOT IN('resolved','closed')");if($r)$counts['critical']=(int)$r->fetch_assoc()['n'];$r=$db->query("SELECT COUNT(*) n FROM io_security_incidents WHERE notification_required='yes' AND status NOT IN('resolved','closed')");if($r)$counts['notification']=(int)$r->fetch_assoc()['n'];$r=$db->query("SELECT COUNT(*) n FROM io_security_incident_actions WHERE status IN('open','in_progress','overdue')");if($r)$counts['actions']=(int)$r->fetch_assoc()['n'];
function bm_select(string $name,array $opts,string $selected):string{$o='<select name="'.bm_e($name).'">';foreach($opts as $v=>$label)$o.='<option value="'.bm_e($v).'"'.($v===$selected?' selected':'').'>'.bm_e($label).'</option>';$o.='</select>';return $o;}
?>
